"""
    Helper function that sorts each of the smaller arrays from merge_sort.

    Help from:
    https://codereview.stackexchange.com/questions/154135/recursive-merge-sort-in-python.
    """
def merge(a: Any, b: Any) -> object {
    merged = [];
    (i, j) = (0, 0);
    while ((i < len(a)) and (j < len(b))) {
        if (a[i] < b[j]) {
            merged.append(a[i]);
            i += 1;
        } else {
            merged.append(b[j]);
            j += 1;
        }
    }
    merged += a[i:];
    merged += b[j:];
    return merged;
}

"""Helper function to summarize the top hit at a given rank."""
def summarize_cag_taxa(cag_id: Any, cag_tax_df: Any, taxa_rank: Any) -> object {
    if (cag_tax_df is None) {
        return {
            "CAG": cag_id,
            "name": 'none',
            "label": "No genes assigned at this level"
        };
    }
    return {
        "CAG": cag_id,
        "name": cag_tax_df["name"].values[0],
        "label": "{}<br>{:,} genes assigned".format(
            cag_tax_df["name"].values[0], int(cag_tax_df["count"].values[0])
        )
    };
}

